// Clean & Normalize Lead Data
// Receives the lead from the webhook and creates clean,
// consistent fields for validation, enrichment, scoring, and CRM.

return $input.all().map(item => {
  const data = item.json.body || item.json;

  // -----------------------------
  // 1. Clean basic lead fields
  // -----------------------------

  const name = String(data.name || '').trim();

  const email = String(data.email || '')
    .trim()
    .toLowerCase();

  const companyName = String(data.companyName || '')
    .trim();

  const website = String(data.website || '')
    .trim();

  // -----------------------------
  // 2. Split name into first/last
  // -----------------------------

  const nameParts = name.split(/\s+/).filter(Boolean);

  const firstName = nameParts.length > 0
    ? nameParts[0]
    : '';

  const lastName = nameParts.length > 1
    ? nameParts.slice(1).join(' ')
    : '';

  // -----------------------------
  // 3. Clean company name
  // Removes common legal suffixes
  // -----------------------------

  const cleanCompanyName = companyName
    .replace(
      /\b(ltd|limited|llc|inc|incorporated|corp|corporation|co|company|plc)\b\.?/gi,
      ''
    )
    .replace(/\s+/g, ' ')
    .trim();

  // -----------------------------
  // 4. Normalize website/domain
  // -----------------------------

  let domain = website
    .toLowerCase()
    .trim();

  // Remove protocol
  domain = domain.replace(/^https?:\/\//, '');

  // Remove www.
  domain = domain.replace(/^www\./, '');

  // Remove everything after the domain
  domain = domain.split('/')[0];

  // Remove query string and hash
  domain = domain.split('?')[0];
  domain = domain.split('#')[0];

  // Remove trailing dot
  domain = domain.replace(/\.$/, '');

  // -----------------------------
  // 5. Validate basic format
  // -----------------------------

  const missingFields = [];

  if (!name) {
    missingFields.push('name');
  }

  if (!email) {
    missingFields.push('email');
  }

  if (!companyName) {
    missingFields.push('companyName');
  }

  if (!website) {
    missingFields.push('website');
  }

  // -----------------------------
  // 6. Return clean lead
  // -----------------------------

  return {
    json: {
      ...data,

      // Original cleaned fields
      name,
      email,
      companyName,
      website,

      // Normalized fields
      firstName,
      lastName,
      cleanCompanyName,
      domain,

      // Validation helper
      missingFields,
      isValidBasicData: missingFields.length === 0
    }
  };
});

// ==========================================
// CALCULATE LEAD SCORE
// Uses the data received directly from Merge1
// ==========================================

const items = $input.all();

return items.map((item) => {
  const data = item.json || {};

  // ------------------------------------------
  // 1. BASIC LEAD DATA
  // ------------------------------------------
  const firstName = data.firstName || '';
  const lastName = data.lastName || '';
  const name = data.name || `${firstName} ${lastName}`.trim();
  const email = data.email || '';
  const companyName = data.companyName || data.company_name || '';
  const website = data.website || '';
  const country = data.country || '';

  // ------------------------------------------
  // 2. COMPANY ENRICHMENT DATA
  // ------------------------------------------
  const industry = data.industry || '';
  const employeeCount =
    Number(data.employee_count) ||
    Number(data.employeeCount) ||
    0;

  const employeeBand =
    data.employee_band ||
    data.employeeBand ||
    '';

  // ------------------------------------------
  // 3. CONTACT ENRICHMENT DATA
  // ------------------------------------------
  const scrapedEmails = Array.isArray(data.emails)
    ? data.emails
    : [];

  const scrapedPhones = Array.isArray(data.phones)
    ? data.phones
    : [];

  const linkedIns = Array.isArray(data.linkedIns)
    ? data.linkedIns
    : [];

  const twitters = Array.isArray(data.twitters)
    ? data.twitters
    : [];

  // ------------------------------------------
  // 4. SCORING
  // ------------------------------------------
  let score = 0;
  const reasons = [];

  // COUNTRY SCORE
  const normalizedCountry = country.toLowerCase().trim();

  if (
    normalizedCountry === 'united states' ||
    normalizedCountry === 'usa' ||
    normalizedCountry === 'us'
  ) {
    score += 50;
    reasons.push('Tier-1 country (US): +50');
  } else if (
    normalizedCountry === 'united kingdom' ||
    normalizedCountry === 'uk'
  ) {
    score += 40;
    reasons.push('Tier-1 country (UK): +40');
  } else if (country) {
    score += 20;
    reasons.push(`Country identified (${country}): +20`);
  } else {
    reasons.push('Country unavailable: +0');
  }

  // COMPANY SIZE SCORE
  if (employeeCount >= 1000) {
    score += 30;
    reasons.push(`Large company (${employeeCount}+ employees): +30`);
  } else if (employeeCount >= 100) {
    score += 20;
    reasons.push(`Medium company (${employeeCount}+ employees): +20`);
  } else if (employeeCount >= 10) {
    score += 10;
    reasons.push(`Small company (${employeeCount}+ employees): +10`);
  } else if (employeeBand) {
    score += 10;
    reasons.push(`Employee band available (${employeeBand}): +10`);
  } else {
    reasons.push('Employee count unavailable: +0');
  }

  // INDUSTRY SCORE
  if (industry) {
    score += 10;
    reasons.push(`Industry identified (${industry}): +10`);
  } else {
    reasons.push('Industry unavailable: +0');
  }

  // CONTACT INFORMATION SCORE
  if (email) {
    score += 5;
    reasons.push('Lead email provided: +5');
  }

  if (scrapedEmails.length > 0) {
    score += 5;
    reasons.push('Public company email found: +5');
  }

  // Keep score between 0 and 100
  score = Math.min(score, 100);

  // ------------------------------------------
  // 5. LEAD TEMPERATURE
  // ------------------------------------------
  let leadTemperature;

  if (score >= 70) {
    leadTemperature = 'Hot';
  } else if (score >= 40) {
    leadTemperature = 'Warm';
  } else {
    leadTemperature = 'Cold';
  }

  // ------------------------------------------
  // 6. RETURN CLEAN RESULT
  // ------------------------------------------
  return {
    json: {
      ...data,

      firstName,
      lastName,
      name,
      email,
      companyName,
      website,
      country,

      companyEnrichment: {
        industry,
        employee_count: employeeCount || null,
        employee_band: employeeBand
      },

      contactEnrichment: {
        emails: scrapedEmails,
        phones: scrapedPhones,
        linkedIns,
        twitters
      },

      leadScore: score,
      leadTemperature,
      scoringReasons: reasons
    }
  };
});

